net.ipv4.tcp_tw_reuse = 1
fs.file-max = 2097152`}],Mz=({isOpen:e,onClose:t,initialFilePath:r="/etc/nginx/nginx.conf",initialContent:n="",onSaveToRemote:i})=>{const[l,o]=T.useState(r),[a,c]=T.useState(n||_f[0].content),[d,f]=T.useState(n||_f[0].content),[u,m]=T.useState("editor"),[v,_]=T.useState(!1),[g,h]=T.useState(!1);if(!e)return null;const p=w=>{o(w.path),c(w.content),f(w.content)},x=()=>{i&&i(l,d),_(!0),setTimeout(()=>_(!1),2500)},b=()=>{navigator.clipboard.writeText(d),h(!0),setTimeout(()=>h(!1),2e3)},y=a.split(`
